import{_ as o,c as t,o as a,ag as s}from"./chunks/framework.DZ_cNctr.js";const d=JSON.parse('{"title":"Video script: Annotations","description":"","frontmatter":{},"headers":[],"relativePath":"scripts/annotations-video.md","filePath":"scripts/annotations-video.md"}'),r={name:"scripts/annotations-video.md"};function l(n,e,i,c,u,h){return a(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="video-script-annotations" tabindex="-1">Video script: Annotations <a class="header-anchor" href="#video-script-annotations" aria-label="Permalink to &quot;Video script: Annotations&quot;">​</a></h1><p><strong>Target length</strong>: ~90 seconds <strong>Audience</strong>: Pathologists / cell biologists evaluating the viewer <strong>Call to action</strong>: Open the demo, try the Select tool, draw something</p><p>The existing YouTube intro (Local Files, HCS Plates) is the template: tight voiceover, fast cuts, no jargon in the first 10 seconds.</p><hr><h2 id="cold-open-0-00-–-0-08" tabindex="-1">Cold open (0:00 – 0:08) <a class="header-anchor" href="#cold-open-0-00-–-0-08" aria-label="Permalink to &quot;Cold open (0:00 – 0:08)&quot;">​</a></h2><p><strong>Visual</strong>: WSI loaded in viewer. A handful of pre-drawn annotations: three tumor polygons, two stroma, a necrosis region. Labels visible.</p><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Annotations in Find Nuclei Viewer. Draw regions, classify them, and edit hundreds at once.&quot;</p></blockquote><hr><h2 id="draw-a-polygon-0-08-–-0-20" tabindex="-1">Draw a polygon (0:08 – 0:20) <a class="header-anchor" href="#draw-a-polygon-0-08-–-0-20" aria-label="Permalink to &quot;Draw a polygon (0:08 – 0:20)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Cursor moves to the Polygon tool in the toolbar. Click.</li><li>Cursor returns to the canvas. Click-click-click-click around a cell cluster. Double-click to close.</li><li>A red polygon fills the region.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Click to place vertices. Double-click to close. Or press-and-drag for freehand. The path is simplified on release, so a scribble becomes a clean polygon.&quot;</p></blockquote><p><strong>Optional cut</strong>: show the freehand version on a second region (2 seconds).</p><hr><h2 id="templates-for-fast-classification-0-20-–-0-35" tabindex="-1">Templates for fast classification (0:20 – 0:35) <a class="header-anchor" href="#templates-for-fast-classification-0-20-–-0-35" aria-label="Permalink to &quot;Templates for fast classification (0:20 – 0:35)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>On-canvas template chip row appears while polygon tool is active: &quot;Tumor&quot;, &quot;Stroma&quot;, &quot;Necrosis&quot;, &quot;Immune&quot; colored chips.</li><li>Click &quot;Stroma&quot;. The chip lights up green.</li><li>Draw another polygon. It automatically fills green and labels as &quot;Stroma 3&quot;.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Templates pre-set the color and class. Pick one, and every polygon you draw next inherits it: color, class, sequential label, all in one click. Alt-1 through 9 for keyboard shortcuts.&quot;</p></blockquote><hr><h2 id="select-and-reshape-0-35-–-0-50" tabindex="-1">Select and reshape (0:35 – 0:50) <a class="header-anchor" href="#select-and-reshape-0-35-–-0-50" aria-label="Permalink to &quot;Select and reshape (0:35 – 0:50)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Switch to Select tool (V key overlay shown briefly).</li><li>Click a polygon. Vertex handles appear as white dots.</li><li>Drag a handle outward. The polygon reshapes live.</li><li>Drag a midpoint. A new vertex appears.</li><li>Press <code>Escape</code>.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Select mode shows vertex handles. Drag any corner to reshape. Drag between corners to add a new vertex. Polygons also support freehand reshape. Hold a corner and sketch a new arc.&quot;</p></blockquote><hr><h2 id="multi-select-and-lasso-0-50-–-1-05" tabindex="-1">Multi-select and lasso (0:50 – 1:05) <a class="header-anchor" href="#multi-select-and-lasso-0-50-–-1-05" aria-label="Permalink to &quot;Multi-select and lasso (0:50 – 1:05)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Cmd+click two rows in the annotation list. Green borders appear, bulk action bar slides in showing &quot;2 selected&quot;.</li><li>Switch to Select tool on canvas. Draw a loop around a cluster. Dashed green lasso path.</li><li>Release. Five annotations get green halos, list shows &quot;5 selected&quot;.</li><li>Bulk bar: pick &quot;Tumor&quot; from the Template dropdown. Every selected annotation turns red, reclassifies.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Cmd-click the list to multi-select. Or drag a freehand lasso on canvas. Anything fully inside joins the selection. Then bulk apply a template, change color, hide, or delete. All in one undoable step.&quot;</p></blockquote><hr><h2 id="group-move-cleanup-1-05-–-1-20" tabindex="-1">Group move + cleanup (1:05 – 1:20) <a class="header-anchor" href="#group-move-cleanup-1-05-–-1-20" aria-label="Permalink to &quot;Group move + cleanup (1:05 – 1:20)&quot;">​</a></h2><p><strong>Visual</strong>:</p><ul><li>Drag one of the still-selected polygons; all five move together.</li><li>Press arrow keys. The group nudges by one pixel.</li><li>Shift+arrow jumps 10 pixels.</li><li>Press Escape. Selection clears. Halos fade.</li></ul><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Grab any selected shape and the whole group follows. Arrow keys nudge by a pixel. Shift-arrow jumps ten. Escape to clear.&quot;</p></blockquote><hr><h2 id="close-1-20-–-1-30" tabindex="-1">Close (1:20 – 1:30) <a class="header-anchor" href="#close-1-20-–-1-30" aria-label="Permalink to &quot;Close (1:20 – 1:30)&quot;">​</a></h2><p><strong>Visual</strong>: Zoom out to full tissue. All annotations colored by class (tumor red, stroma green, necrosis yellow). Legend card visible bottom-right.</p><p><strong>Voiceover</strong>:</p><blockquote><p>&quot;Works on any OME-Zarr image. Saves to your browser. Share a URL and a reviewer opens the same view. Try it at find-nuclei dot github dot io.&quot;</p></blockquote><p><strong>On-screen text</strong>: <code>find-nuclei.github.io</code></p><hr><h2 id="production-notes" tabindex="-1">Production notes <a class="header-anchor" href="#production-notes" aria-label="Permalink to &quot;Production notes&quot;">​</a></h2><ul><li><strong>Screen capture resolution</strong>: 1920×1080, retina source preferred.</li><li><strong>Cursor</strong>: show the OS cursor, bump its size one step above default.</li><li><strong>Keypresses</strong>: show a key-cap overlay for V, Esc, Cmd-click, Shift-click. The YouTube reference videos use <code>screen-studio.com</code>-style key caps.</li><li><strong>Music</strong>: none or very quiet. The Local Files video has no music. Keep consistent.</li><li><strong>Pace</strong>: aim for 4–5 cuts per 30 seconds. Never hold a shot more than 5 seconds without a cursor movement or UI change.</li><li><strong>Thumbnail candidate</strong>: the multi-select halo shot (0:55 area). It&#39;s visually distinctive.</li></ul><h2 id="screenshot-tie-in" tabindex="-1">Screenshot tie-in <a class="header-anchor" href="#screenshot-tie-in" aria-label="Permalink to &quot;Screenshot tie-in&quot;">​</a></h2><p>All screenshot placeholders in the guide correspond to stills we should grab during the video shoot. Save them to <code>docs/public/screenshots/annotations-*.png</code> as we pause at each beat.</p>',50)])])}const g=o(r,[["render",l]]);export{d as __pageData,g as default};
